-- eAcharya Phase 5: NCERT-aligned Geography learning content for Classes 9-12.
-- Adds original study guides, practice activities, chapter worksheet resources and official textbook links.
-- No copyrighted textbook chapter text or PDF is copied into this migration.
-- Review content/course changes and back up production data before applying.
INSERT INTO public.classes (grade, name, description, is_active) VALUES
  (9, 'Class 9', 'NCERT-aligned Geography foundations', true),
  (10, 'Class 10', 'NCERT-aligned resources and development', true),
  (11, 'Class 11', 'Physical Geography and India physical environment', true),
  (12, 'Class 12', 'Human Geography and India people and economy', true)
ON CONFLICT (grade) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

INSERT INTO public.subjects (name, slug, description, is_active) VALUES
  ('Geography', 'geography', 'Geography learning content for Classes 9-12.', true)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- Preserve the two existing live courses in this database by normalising their slugs in place.
-- This keeps course IDs, enrolments, units, assessments and references intact.
UPDATE public.courses
SET title = 'Class 9 Geography: Contemporary India I',
    slug = 'class-9-contemporary-india-i',
    description = 'NCERT-aligned learning course for Class 9 Geography. Includes original study guides, chapter practice worksheets and links to official textbook resources.',
    status = 'published',
    updated_at = now()
WHERE slug = 'class-9-contemporary-india-1'
  AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-9-contemporary-india-i');

UPDATE public.courses
SET title = 'Class 10 Geography: Contemporary India II',
    slug = 'class-10-contemporary-india-ii',
    description = 'NCERT-aligned Class 10 Geography with original chapter notes, applied worksheets and official textbook links.',
    status = 'published',
    updated_at = now()
WHERE slug = 'class-10-contemporary-india-2'
  AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-10-contemporary-india-ii');

-- Rename legacy placeholder courses only when no canonical row exists, retaining course IDs and assessment references.
UPDATE public.courses SET title = 'Class 9 Geography: Contemporary India I', slug = 'class-9-contemporary-india-i', description = 'NCERT-aligned learning course for Class 9 Geography. Includes original study guides, chapter practice worksheets and links to official textbook resources.', status = 'published', updated_at = now() WHERE slug = 'sample-class-9-geography' AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-9-contemporary-india-i');
UPDATE public.courses SET title = 'Class 10 Geography: Contemporary India II', slug = 'class-10-contemporary-india-ii', description = 'NCERT-aligned Class 10 Geography with original chapter notes, applied worksheets and official textbook links.', status = 'published', updated_at = now() WHERE slug = 'sample-class-10-resources-development' AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-10-contemporary-india-ii');
UPDATE public.courses SET title = 'Class 11 Geography: Fundamentals of Physical Geography', slug = 'class-11-fundamentals-physical-geography', description = 'NCERT-aligned foundations of Earth systems, landforms, atmosphere and oceans, with original study notes and practice worksheets.', status = 'published' WHERE slug = 'sample-class-11-physical-geography' AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-11-fundamentals-physical-geography');
UPDATE public.courses SET title = 'Class 12 Geography: Fundamentals of Human Geography', slug = 'class-12-fundamentals-human-geography', description = 'NCERT-aligned human geography: population, development, activities, transport and trade. Includes original study guides and applied worksheets.', status = 'published' WHERE slug = 'sample-class-12-human-geography' AND NOT EXISTS (SELECT 1 FROM public.courses target WHERE target.slug = 'class-12-fundamentals-human-geography');

-- Ensure every NCERT-aligned book course exists, whether or not the starter sample course was present.
INSERT INTO public.courses (title, slug, description, class_id, subject_id, status)
SELECT b.title, b.slug, b.description, cl.id, su.id, 'published'
FROM (VALUES
  (9, 'class-9-contemporary-india-i', 'Class 9 Geography: Contemporary India I', 'NCERT-aligned learning course for Class 9 Geography. Includes original study guides, chapter practice worksheets and links to official textbook resources.'),
  (10, 'class-10-contemporary-india-ii', 'Class 10 Geography: Contemporary India II', 'NCERT-aligned Class 10 Geography with original chapter notes, applied worksheets and official textbook links.'),
  (11, 'class-11-fundamentals-physical-geography', 'Class 11 Geography: Fundamentals of Physical Geography', 'NCERT-aligned foundations of Earth systems, landforms, atmosphere and oceans, with original study notes and practice worksheets.'),
  (11, 'class-11-india-physical-environment', 'Class 11 Geography: India — Physical Environment', 'NCERT-aligned study of India’s location, relief, drainage, climate, vegetation and natural hazards with original notes and worksheets.'),
  (12, 'class-12-fundamentals-human-geography', 'Class 12 Geography: Fundamentals of Human Geography', 'NCERT-aligned human geography: population, development, activities, transport and trade. Includes original study guides and applied worksheets.'),
  (12, 'class-12-india-people-and-economy', 'Class 12 Geography: India — People and Economy', 'NCERT-aligned Indian population, settlements, agriculture, water, resources, planning, transport and trade, with original study guides and worksheets.')
) AS b(grade, slug, title, description)
JOIN public.classes cl ON cl.grade = b.grade
JOIN public.subjects su ON su.slug = 'geography'
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, status = 'published';

-- Temporary course/chapter catalogue. The chapter names mirror current commonly available NCERT book structures; verify the current CBSE syllabus before formal use.
CREATE TEMP TABLE IF NOT EXISTS phase5_books (book_slug text PRIMARY KEY, grade smallint, title text, description text, official_url text, book_name text);
TRUNCATE TABLE phase5_books;
CREATE TEMP TABLE IF NOT EXISTS phase5_chapters (book_slug text, chapter_position integer, chapter_title text, focus text, activity text, question_one text, question_two text, objective_one text, objective_two text, PRIMARY KEY (book_slug, chapter_position));
TRUNCATE TABLE phase5_chapters;
INSERT INTO phase5_books (book_slug, grade, title, description, official_url, book_name) VALUES
  ('class-9-contemporary-india-i', 9, 'Class 9 Geography: Contemporary India I', 'NCERT-aligned learning course for Class 9 Geography. Includes original study guides, chapter practice worksheets and links to official textbook resources.', 'https://ncert.nic.in/textbook.php?jess1=0-6', 'Contemporary India I'),
  ('class-10-contemporary-india-ii', 10, 'Class 10 Geography: Contemporary India II', 'NCERT-aligned Class 10 Geography with original chapter notes, applied worksheets and official textbook links.', 'https://ncert.nic.in/textbook.php?jess2=0-7', 'Contemporary India II'),
  ('class-11-fundamentals-physical-geography', 11, 'Class 11 Geography: Fundamentals of Physical Geography', 'NCERT-aligned foundations of Earth systems, landforms, atmosphere and oceans, with original study notes and practice worksheets.', 'https://ncert.nic.in/textbook.php?kegy2=0-14', 'Fundamentals of Physical Geography'),
  ('class-11-india-physical-environment', 11, 'Class 11 Geography: India — Physical Environment', 'NCERT-aligned study of India’s location, relief, drainage, climate, vegetation and natural hazards with original notes and worksheets.', 'https://ncert.nic.in/textbook.php?kegy1=0-6', 'India Physical Environment'),
  ('class-12-fundamentals-human-geography', 12, 'Class 12 Geography: Fundamentals of Human Geography', 'NCERT-aligned human geography: population, development, activities, transport and trade. Includes original study guides and applied worksheets.', 'https://ncert.nic.in/textbook.php?legy1=0-8', 'Fundamentals of Human Geography'),
  ('class-12-india-people-and-economy', 12, 'Class 12 Geography: India — People and Economy', 'NCERT-aligned Indian population, settlements, agriculture, water, resources, planning, transport and trade, with original study guides and worksheets.', 'https://ncert.nic.in/textbook.php?legy2=0-9', 'India: People and Economy');

INSERT INTO phase5_chapters (book_slug, chapter_position, chapter_title, focus, activity, question_one, question_two, objective_one, objective_two) VALUES
  ('class-9-contemporary-india-i', 0, 'India — Size and Location', 'India occupies a central position in the Indian Ocean region and spans a wide range of latitudes and longitudes. Absolute location helps identify a place, while relative location explains its connections with neighbouring regions, sea routes and time zones. The Tropic of Cancer crosses the country, and the Standard Meridian provides a common reference for Indian Standard Time.', 'On an outline map, mark the Tropic of Cancer, Standard Meridian, mainland extremes and neighbouring countries.', 'How do latitude and longitude describe India’s location?', 'Why does a country use one standard time?', 'Explain absolute and relative location using India as an example.', 'Locate major reference lines and neighbouring countries on a map.'),
  ('class-9-contemporary-india-i', 1, 'Physical Features of India', 'India’s relief includes the Himalayan mountains, Northern Plains, Peninsular Plateau, Indian Desert, Coastal Plains and Islands. Their rocks, landforms and geological histories differ, shaping drainage, soils, settlement, transport and livelihoods. A physical map is most useful when relief patterns are connected with human activities.', 'Make a labelled relief sketch of India and add one way each region influences life or economic activity.', 'How do the Himalayas differ from the Peninsular Plateau in origin and relief?', 'How can relief influence settlement and transport?', 'Describe India’s major physiographic divisions.', 'Relate relief to drainage, farming or settlement.'),
  ('class-9-contemporary-india-i', 2, 'Drainage', 'A drainage system is made up of a river and its tributaries within a drainage basin. Himalayan rivers are generally supplied by rainfall and snowmelt, whereas many Peninsular rivers depend more directly on seasonal rainfall and flow across older plateau terrain. River patterns support water supply and farming but also create flood, pollution and management challenges.', 'Draw a simple drainage basin with a trunk stream, tributaries, watershed and mouth; compare one Himalayan and one Peninsular river.', 'What is a drainage basin?', 'Why do many Peninsular rivers show stronger seasonal variation?', 'Identify the parts of a drainage basin.', 'Compare the broad characteristics of Himalayan and Peninsular rivers.'),
  ('class-9-contemporary-india-i', 3, 'Climate', 'India’s climate is strongly influenced by monsoon circulation, relief, latitude, distance from the sea and seasonal pressure differences. The year is commonly studied through seasonal patterns rather than a single annual average. Rainfall varies greatly across the country, so agriculture, water availability and hazard exposure also vary spatially.', 'Use a month-by-month rainfall chart for a place near you to identify wet and dry seasons; compare it with another region.', 'How does the monsoon affect the annual distribution of rainfall?', 'Name two factors that explain regional climate differences in India.', 'Explain major controls of India’s climate.', 'Interpret a seasonal rainfall graph.'),
  ('class-9-contemporary-india-i', 4, 'Natural Vegetation and Wildlife', 'Natural vegetation reflects the interaction of temperature, rainfall, soil, relief and human influence. Forest types differ in structure and species, from wet evergreen forests to thorn vegetation and mountain forests. Habitat loss and fragmentation make conservation, protected areas and community stewardship important.', 'Compare the climatic conditions associated with two vegetation types and prepare a small conservation action plan for a local habitat.', 'Why does vegetation vary from one region to another?', 'How can habitat fragmentation affect wildlife?', 'Relate vegetation patterns to climatic conditions.', 'Explain why biodiversity conservation needs multiple approaches.'),
  ('class-9-contemporary-india-i', 5, 'Population', 'Population geography studies where people live, how population changes and how population composition varies. Distribution and density are not uniform because physical conditions, jobs, transport, historical settlement and public services differ. Age structure, sex ratio, literacy and occupational composition help explain social and economic needs.', 'Create a small table for a district using an official census or government source and describe two spatial patterns without treating old census data as current.', 'How is population density calculated?', 'Why can two regions with similar area have very different population densities?', 'Distinguish population distribution, density and growth.', 'Interpret population indicators with attention to data year and scale.'),
  ('class-10-contemporary-india-ii', 0, 'Resources and Development', 'Resources become useful through human knowledge, technology and institutions, but use must account for renewability, distribution and environmental cost. Resource planning connects inventory, appropriate technology and conservation. Soil types and land degradation show why development decisions need local and regional evidence.', 'Choose one local resource, map its use and propose two practical conservation steps.', 'How does resource planning differ from simply extracting more resources?', 'Name two causes of land degradation and ways to reduce them.', 'Classify resources using more than one criterion.', 'Connect resource planning with sustainable development.'),
  ('class-10-contemporary-india-ii', 1, 'Forest and Wildlife Resources', 'Biodiversity supports ecological processes, livelihoods and cultural practices. Forest and wildlife loss can result from habitat change, extraction, infrastructure and conflicting land uses. Conservation uses protected areas, laws, restoration and participation by local communities; no single strategy works in every context.', 'Prepare a case-study card on a protected area or community conservation effort, including location, ecosystem and challenge.', 'What is the difference between conservation and preservation?', 'Why is community participation useful in biodiversity protection?', 'Explain threats to forests and wildlife.', 'Compare conservation approaches using a case study.'),
  ('class-10-contemporary-india-ii', 2, 'Water Resources', 'Freshwater is renewable through the water cycle but locally limited by season, storage, quality and demand. Rivers, groundwater, tanks and reservoirs support households, agriculture and industry. Large projects can deliver benefits while also producing displacement and ecological costs; watershed management and rainwater harvesting can complement supply infrastructure.', 'Map where your locality gets water and identify one demand-management and one recharge option.', 'Why can a water-scarce area still experience floods?', 'Give one benefit and one possible cost of a multipurpose river project.', 'Explain competing uses of water.', 'Evaluate water management at local scale.'),
  ('class-10-contemporary-india-ii', 3, 'Agriculture', 'Agriculture depends on climate, soils, relief, water, labour, technology and market access. Cropping seasons and crop choices vary by region; yield measures output per unit area and should not be confused with total production. Irrigation, seed quality, credit, storage and market conditions influence farm outcomes.', 'Compare one food crop and one cash crop using rainfall needs, season, major producing regions and yield units.', 'How is crop yield different from total production?', 'How do irrigation and market access influence crop choice?', 'Describe major factors shaping Indian agriculture.', 'Interpret crop-production data with units and years.'),
  ('class-10-contemporary-india-ii', 4, 'Minerals and Energy Resources', 'Minerals form under particular geological conditions, so their locations are uneven. Energy systems combine conventional sources such as coal and petroleum with renewable options such as solar, wind and hydropower. Resource planning weighs reliability, affordability, access, pollution and long-term sustainability.', 'Mark a few mineral and energy regions on a map, then compare one fossil-fuel source and one renewable source.', 'Why are mineral deposits spatially concentrated?', 'What trade-offs arise when comparing coal with solar power?', 'Relate geology to mineral distribution.', 'Compare energy sources using environmental and economic criteria.'),
  ('class-10-contemporary-india-ii', 5, 'Manufacturing Industries', 'Industries locate where combinations of raw materials, labour, energy, markets, transport, capital and policy make production viable. Agro-based and mineral-based industries often have different location patterns. Industrial activity creates jobs and products but may also pollute air, water and land without effective regulation.', 'Choose an industry and make a location-factor diagram; include one environmental safeguard.', 'Why do industries not distribute evenly across all regions?', 'How can industrial pollution be reduced?', 'Explain major industrial location factors.', 'Evaluate the benefits and costs of industrial development.'),
  ('class-10-contemporary-india-ii', 6, 'Lifelines of National Economy', 'Transport and communication connect production areas, markets and people, helping trade and access to services. Road, rail, waterways, ports, air routes and digital networks have different capacities, costs and geographic constraints. Connectivity can support regional development, but investment and access may remain uneven.', 'Map a product’s journey from producer to market and identify the transport links involved.', 'How do transport networks support economic activity?', 'Why may a shorter route not always be the most efficient?', 'Compare transport modes and their uses.', 'Explain how connectivity influences regional development.'),
  ('class-11-fundamentals-physical-geography', 0, 'Geography as a Discipline', 'Geography asks where phenomena occur, why their patterns vary and how places connect. Physical geography studies natural systems; human geography studies people and their activities; regional approaches integrate both. Scale, location, spatial pattern and interaction are core tools for explaining places.', 'Choose a local issue and separate its physical factors, human factors and spatial connections.', 'What makes a geographical explanation different from a simple description?', 'How do physical and human geography complement each other?', 'Explain geography’s integrative nature.', 'Use spatial questions to organise a case study.'),
  ('class-11-fundamentals-physical-geography', 1, 'The Origin and Evolution of the Earth', 'Scientific explanations of Earth’s origin are built from evidence about the solar system, rocks, meteorites and planetary processes. Earth has changed through long geological time, and its early development established conditions for the crust, atmosphere, oceans and life. Scientific models are updated when evidence improves.', 'Make a timeline that places planetary formation, crust development and early life in sequence without implying exact certainty where it is not known.', 'Why do scientists use multiple kinds of evidence to study Earth’s origin?', 'How can planetary evolution affect surface environments?', 'Summarise the broad sequence of Earth’s early development.', 'Distinguish a scientific model from unsupported speculation.'),
  ('class-11-fundamentals-physical-geography', 2, 'Interior of the Earth', 'Earth’s interior cannot be observed directly at great depth, so geographers and geophysicists use seismic waves, gravity, density and samples to infer its structure. The crust, mantle and core differ in composition and physical properties. These internal differences help explain tectonic activity and the creation of landforms.', 'Draw a labelled cross-section showing crust, mantle and core, then annotate which evidence helps infer the layers.', 'How do seismic waves help reveal Earth’s interior?', 'What is the broad difference between crust and mantle?', 'Describe the main internal layers of Earth.', 'Explain how indirect evidence supports internal-earth models.'),
  ('class-11-fundamentals-physical-geography', 3, 'Distribution of Oceans and Continents', 'Continents and ocean basins have changed through geological time. Continental drift proposed movement of landmasses, while plate tectonic theory explains movement through interacting lithospheric plates and processes at plate boundaries. Present-day patterns of mountains, trenches and earthquakes provide evidence of ongoing change.', 'Use a world plate map to identify one convergent, divergent and transform boundary and predict a typical feature at each.', 'What evidence supports continental movement?', 'How do plate boundaries produce different landforms and hazards?', 'Outline the idea of continental drift and plate tectonics.', 'Relate plate-boundary type to likely surface processes.'),
  ('class-11-fundamentals-physical-geography', 4, 'Minerals and Rocks', 'Minerals have characteristic chemical composition and physical properties, while rocks are aggregates of one or more minerals. Igneous, sedimentary and metamorphic rocks form through different processes and can transform through the rock cycle. Rock type affects landforms, soils, construction and resource use.', 'Collect or photograph local rock examples if available and classify them only when evidence supports the classification.', 'How are minerals different from rocks?', 'How can one rock type transform into another?', 'Classify major rock types by formation.', 'Use observable properties carefully when describing rocks.'),
  ('class-11-fundamentals-physical-geography', 5, 'Geomorphic Processes', 'Landforms change through endogenic forces from within Earth and exogenic processes operating at the surface. Weathering breaks material down, erosion transports it and deposition lays it down elsewhere. The rate and outcome depend on rock, climate, slope, water, vegetation and time.', 'Create a process chain showing how weathering, erosion and deposition can reshape a slope or river valley.', 'How does weathering differ from erosion?', 'Why can the same process create different results in different environments?', 'Distinguish major geomorphic processes.', 'Connect process, material and landform.'),
  ('class-11-fundamentals-physical-geography', 6, 'Landforms and their Evolution', 'Fluvial, glacial, aeolian, coastal and groundwater processes create distinctive landforms through erosion and deposition. A landform is not simply a shape; it records the processes and environmental conditions that acted over time. Reading photographs and topographic maps helps infer how a landscape developed.', 'Select a landform photograph and annotate the likely process, energy source and evidence visible in the image.', 'What features might indicate river deposition?', 'How can wind and ice create contrasting landforms?', 'Identify landforms associated with major geomorphic agents.', 'Use visual evidence to infer landscape processes.'),
  ('class-11-fundamentals-physical-geography', 7, 'Composition and Structure of Atmosphere', 'The atmosphere is a mixture of gases and suspended particles organised into layers with different temperature patterns and functions. Water vapour varies through space and time and is central to weather. Atmospheric composition helps regulate energy balance and protects life, while pollutants can alter air quality.', 'Draw the atmospheric layers with one characteristic of each and explain why the vertical temperature pattern is not uniform.', 'Why is water vapour important despite its variable amount?', 'How do the troposphere and stratosphere differ?', 'Describe the composition and broad structure of the atmosphere.', 'Relate atmospheric layers to weather and environmental processes.'),
  ('class-11-fundamentals-physical-geography', 8, 'Solar Radiation, Heat Balance and Temperature', 'Incoming solar energy is uneven because of latitude, season, day length, cloud cover and surface characteristics. Earth absorbs, reflects and emits energy; the balance between incoming and outgoing energy influences temperature. Land and water heat differently, so coastal and inland places can experience different temperature ranges.', 'Compare the seasonal temperature range of a coastal and inland station using an official climate table.', 'What is albedo and how does it affect heating?', 'Why do land and water often heat at different rates?', 'Explain the factors affecting incoming solar energy.', 'Interpret temperature contrasts through energy balance.'),
  ('class-11-fundamentals-physical-geography', 9, 'Atmospheric Circulation and Weather Systems', 'Unequal heating creates pressure differences that help drive atmospheric circulation. Winds are influenced by pressure gradients, Earth’s rotation and friction. Air masses, fronts, cyclones and anticyclones produce changing weather; actual forecasts depend on observed conditions and should be obtained from official weather services.', 'Use a weather map to identify a pressure system and explain the likely wind direction using the map legend.', 'How does a pressure gradient generate wind?', 'Why should weather maps be read with dates and legends?', 'Explain the basic controls of atmospheric circulation.', 'Interpret a simple weather chart responsibly.'),
  ('class-11-fundamentals-physical-geography', 10, 'Water in the Atmosphere', 'Water moves between surface and atmosphere through evaporation, transpiration, condensation and precipitation. Humidity describes moisture in air; cooling can lead to condensation, clouds and fog. Precipitation type and amount depend on uplift, temperature structure and atmospheric conditions.', 'Track a local day’s humidity and rainfall observations and note which additional variables would help explain the outcome.', 'How does condensation contribute to cloud formation?', 'Why is relative humidity sensitive to temperature?', 'Describe key atmospheric moisture processes.', 'Connect uplift and cooling to precipitation.'),
  ('class-11-fundamentals-physical-geography', 11, 'World Climate and Climate Change', 'Climate describes long-term patterns, whereas weather describes short-term atmospheric conditions. Climate regions emerge from interactions among latitude, circulation, altitude, ocean influence and landforms. Climate change refers to persistent shifts in climate statistics, and evidence-based discussion should distinguish long-term trends from single weather events.', 'Compare two climate diagrams and identify differences in rainfall seasonality and temperature range; note the period represented.', 'How is climate different from weather?', 'Why does a single heatwave not alone establish a long-term climate trend?', 'Interpret climate graphs and broad climatic controls.', 'Distinguish variability, extreme events and long-term change.'),
  ('class-11-fundamentals-physical-geography', 12, 'Water (Oceans)', 'Ocean water properties vary by latitude, depth, evaporation, freshwater input and circulation. Temperature and salinity influence density and marine environments. Oceans also store and redistribute heat and form a vital part of the global water and climate systems.', 'Read an ocean temperature or salinity profile and describe how the values change with depth or location.', 'How can evaporation affect salinity?', 'Why are ocean surface conditions important to climate?', 'Explain major variations in ocean-water properties.', 'Interpret ocean data in spatial context.'),
  ('class-11-fundamentals-physical-geography', 13, 'Movements of Ocean Water', 'Waves, tides and ocean currents have different causes and spatial scales. Winds generate many surface waves and currents; tides relate mainly to gravitational attraction; currents redistribute heat, nutrients and organisms. Coastal planning must consider these movements alongside local bathymetry and weather.', 'Sketch the difference between a wave, tidal range and current; identify one human activity affected by each.', 'How do tides differ from wind-driven currents?', 'How can a current influence coastal climate or marine life?', 'Compare major types of ocean movement.', 'Explain how ocean dynamics affect coasts and ecosystems.'),
  ('class-11-india-physical-environment', 0, 'India — Location', 'India’s position in South Asia and the Indian Ocean shapes regional connections, climate, trade and strategic relationships. Latitude influences solar angle and day length, while longitude supports time calculation. Location becomes meaningful when interpreted together with neighbours, seas, relief and transport corridors.', 'Use a political map to identify India’s neighbouring countries and explain one effect of its ocean-facing location.', 'How do latitude and longitude answer different location questions?', 'How can location influence a country’s connections?', 'Describe India’s absolute and relative location.', 'Connect location to physical or human geography.'),
  ('class-11-india-physical-environment', 1, 'Structure and Physiography', 'India’s physical structure includes ancient shield regions and younger mountain belts. Physiographic divisions—Himalayas, Northern Plains, Plateau, Desert, Coastal Plains and Islands—differ in origin, elevation, material and land-use opportunities. Relief also shapes rivers, transport routes, settlement patterns and exposure to hazards.', 'Compare two physiographic divisions by origin, relief, water resources and one human use.', 'Why are the Himalayas geologically different from much of the Peninsular Plateau?', 'How does relief influence river flow?', 'Describe India’s major physiographic divisions.', 'Explain links among relief, water and settlement.'),
  ('class-11-india-physical-environment', 2, 'Drainage System', 'India’s drainage patterns reflect relief, geology, rainfall and geological history. Himalayan systems generally include snowmelt and monsoon inputs, while Peninsular systems flow across older terrain and often respond strongly to seasonal rainfall. River basins cross administrative boundaries, so water planning requires coordination across regions.', 'Trace a major river and tributaries on a map, then identify one upstream-downstream management issue.', 'How do drainage patterns reflect relief?', 'Why does basin-wide planning matter for water management?', 'Compare the broad features of major Indian drainage systems.', 'Use map evidence to discuss river-basin connections.'),
  ('class-11-india-physical-environment', 3, 'Climate', 'India’s climate is shaped by seasonal wind reversal, pressure patterns, relief, latitude and distance from the sea. Monsoon rainfall is spatially uneven and varies from year to year. These variations affect farming calendars, water storage, transport disruption and the risk of droughts or floods.', 'Compare rainfall charts from two Indian regions and connect their seasonal differences to relief or monsoon exposure.', 'What processes contribute to seasonal monsoon circulation?', 'Why can rainfall totals vary sharply over short distances?', 'Explain major controls of India’s climate.', 'Interpret rainfall seasonality using evidence.'),
  ('class-11-india-physical-environment', 4, 'Natural Vegetation', 'Vegetation patterns reflect moisture availability, temperature, elevation and human use. India includes evergreen, deciduous, thorn, montane and mangrove vegetation settings. Human disturbance can change species composition and ecosystem functions, so conservation planning should include habitat connectivity and local livelihoods.', 'Select one vegetation type and create a profile of climate, location, characteristic adaptation and threat.', 'Why do mangroves suit certain coastal environments?', 'How can land-use change affect vegetation patterns?', 'Relate major vegetation types to environment.', 'Explain one conservation measure suitable for a vegetation type.'),
  ('class-11-india-physical-environment', 5, 'Natural Hazards and Disasters', 'Hazards arise from natural processes, but disaster risk depends on exposure, vulnerability and preparedness. Earthquakes, floods, cyclones, landslides, droughts and other events require different monitoring and response strategies. Risk reduction combines reliable warnings, resilient infrastructure, land-use planning, public awareness and inclusive evacuation arrangements.', 'Choose a regional hazard and make a risk matrix separating hazard, exposed people/assets, vulnerability and preparedness.', 'Why does the same hazard affect communities differently?', 'What makes an early-warning system useful?', 'Distinguish hazard, exposure, vulnerability and disaster risk.', 'Propose locally appropriate risk-reduction actions.'),
  ('class-12-fundamentals-human-geography', 0, 'Human Geography: Nature and Scope', 'Human geography examines relationships between people, places and environments. It studies how societies organise space through settlement, livelihood, culture, mobility and technology. Rather than treating physical and human systems separately, a geographical explanation considers interaction, scale, historical context and uneven outcomes.', 'Describe a local place using one physical factor, one social factor, one economic factor and their interactions.', 'What kinds of questions does human geography investigate?', 'Why is scale important in a human-geographical explanation?', 'Explain the scope and integrative nature of human geography.', 'Apply a spatial perspective to a place-based example.'),
  ('class-12-fundamentals-human-geography', 1, 'The World Population: Distribution, Density and Growth', 'Population distribution is uneven because of environmental conditions, economic opportunity, history, technology and policy. Density relates population size to area, while growth depends on births, deaths and migration. Demographic comparisons must record the year, spatial unit and method used for the data.', 'Compare two regions using density and growth figures from the same source and year range.', 'How does population density differ from population growth?', 'Why must demographic data include a reference year?', 'Explain factors that influence population distribution and growth.', 'Calculate or interpret basic population indicators.'),
  ('class-12-fundamentals-human-geography', 2, 'Human Development', 'Human development concerns people’s ability to live healthy, knowledgeable and meaningful lives, not income alone. Measures commonly combine health, education and material living standards, but indices simplify complex realities. Comparing places requires attention to inequality within regions as well as averages between regions.', 'Compare two places using health, education and income indicators, then identify a limitation of using an average score.', 'Why is income alone insufficient to describe development?', 'What can a regional average hide?', 'Describe key dimensions of human development.', 'Evaluate indicators with attention to inequality and scale.'),
  ('class-12-fundamentals-human-geography', 3, 'Primary Activities', 'Primary activities obtain materials directly from nature, including farming, fishing, forestry, mining and gathering. Their location and methods reflect resources, technology, labour, capital, ownership and market access. Modern primary activities range from subsistence livelihoods to highly mechanised commercial production.', 'Compare a subsistence and a commercial primary activity by inputs, output, market connection and environmental effect.', 'How do technology and market access change primary activities?', 'Why are primary activities not limited to agriculture?', 'Classify primary activities and explain their location factors.', 'Compare livelihood systems using multiple criteria.'),
  ('class-12-fundamentals-human-geography', 4, 'Secondary Activities', 'Secondary activities transform raw materials into finished or semi-finished goods. Industrial location depends on material supply, energy, labour, transport, markets, capital, government policy and environmental constraints. New technologies and supply chains can reshape traditional industrial regions.', 'Make a location-factor matrix for a food-processing industry and an iron-and-steel industry.', 'Why can raw-material access matter more to some industries than others?', 'How can transport technology change industrial location?', 'Explain industrial transformation and location.', 'Apply location factors to compare industries.'),
  ('class-12-fundamentals-human-geography', 5, 'Tertiary and Quaternary Activities', 'Tertiary activities provide services such as transport, trade, education and health; quaternary activities focus on knowledge and information. Service economies depend on accessibility, skills, infrastructure and networks. These activities can create opportunities while also displaying unequal access between urban and rural areas.', 'Map the services available within a chosen distance of a settlement and identify who may have difficulty accessing them.', 'How do tertiary and quaternary activities differ?', 'Why does service access vary across regions?', 'Classify service and knowledge-based activities.', 'Evaluate geographic accessibility to services.'),
  ('class-12-fundamentals-human-geography', 6, 'Transport and Communication', 'Transport moves people and goods, while communication transfers information. Networks link places through nodes, routes and flows; their effectiveness depends on cost, speed, capacity, reliability and accessibility. Network investments can reduce distance friction but can also concentrate benefits in already-connected places.', 'Sketch a route network between a producer, distribution centre and market; identify bottlenecks and alternatives.', 'What is the difference between a transport node and a route?', 'How can connectivity produce both benefits and inequalities?', 'Explain how transport and communication organise spatial flows.', 'Interpret networks and accessibility.'),
  ('class-12-fundamentals-human-geography', 7, 'International Trade', 'International trade reflects differences in resources, skills, technology, production costs, demand and policy. Exports and imports connect national economies but expose regions to transport costs, market shifts and changing rules. Trade balance is only one indicator and cannot independently describe overall wellbeing.', 'Trace one traded product from origin to destination and identify production, transport, market and policy factors.', 'Why do countries trade even when they can produce a good domestically?', 'What are two limitations of using trade balance as a wellbeing measure?', 'Explain drivers and basic measures of international trade.', 'Interpret trade relationships across places and scales.'),
  ('class-12-india-people-and-economy', 0, 'Population: Distribution, Density, Growth and Composition', 'India’s population patterns vary by physical conditions, livelihoods, transport, historical settlement and development. Distribution describes where people live, density relates numbers to area, growth records change over time, and composition describes characteristics such as age, sex, literacy and work. Data must be interpreted with the correct census year and boundary.', 'Create a short state profile using population, density and literacy figures, noting the data year and any boundary changes.', 'How do distribution and density answer different questions?', 'Why is it important to identify the year of a population dataset?', 'Explain major dimensions of India’s population geography.', 'Interpret indicators without treating old census values as current.'),
  ('class-12-india-people-and-economy', 1, 'Human Settlements', 'Settlements vary from small rural communities to large metropolitan regions. Their form and function are influenced by site, situation, water, relief, transport, economic activity and historical development. Settlement patterns also reflect planning, land markets, service access and risks such as flooding or heat.', 'Compare one rural and one urban settlement by site, function, transport, services and environmental challenges.', 'How do site and situation differ?', 'Why can the functions of a settlement change over time?', 'Classify settlements by form and function.', 'Relate settlement patterns to connectivity and resources.'),
  ('class-12-india-people-and-economy', 2, 'Land Resources and Agriculture', 'Land is used for farming, forestry, settlement, industry, transport and conservation, and these uses compete with one another. Agriculture varies with soil, climate, irrigation, landholding, labour, technology and markets. Evaluating agricultural performance requires separating cropped area, total production and yield per unit area.', 'Compare two crops using season, water needs, production region and yield; write the units and reference year for all data.', 'How is net sown area different from total cropped area?', 'Why should yield not be confused with total production?', 'Explain land-use categories and agricultural factors.', 'Analyse crop data using consistent units and periods.'),
  ('class-12-india-people-and-economy', 3, 'Water Resources', 'Water availability depends on precipitation, runoff, storage, aquifers, quality, infrastructure and demand. Unequal rainfall does not directly equal unequal access because water management and distribution systems matter. Sustainable planning can combine watershed protection, efficient irrigation, treatment, recharge and community participation.', 'Map one local source of water and identify a supply risk, a quality issue and a demand-management action.', 'Why does physical water availability differ from reliable access?', 'How can groundwater recharge be supported?', 'Describe challenges in water-resource management.', 'Propose integrated local water-management responses.'),
  ('class-12-india-people-and-economy', 4, 'Mineral and Energy Resources', 'India’s minerals and energy resources occur unevenly because of geology and natural conditions. Mining and energy supply support production and infrastructure but can also create pollution, displacement and ecological damage. Energy planning must consider availability, affordability, reliability, emissions and long-term sustainability.', 'Compare a mineral-producing region and an energy-producing region using map evidence and one sustainability issue.', 'Why does mineral distribution depend on geological history?', 'What criteria matter when comparing energy sources?', 'Explain the geography of minerals and energy.', 'Assess resource use with economic and environmental evidence.'),
  ('class-12-india-people-and-economy', 5, 'Planning and Sustainable Development in Indian Context', 'Regional planning aims to improve wellbeing while recognising place-specific conditions and unequal access to resources. Sustainable development links livelihoods, social inclusion and environmental limits. Area-based plans should use evidence, local participation, measurable outcomes and review of unintended effects.', 'Design a one-page sustainable development plan for a dryland, mountain or coastal region with three goals and indicators.', 'Why can one development strategy fail in another region?', 'How can progress toward sustainability be measured?', 'Explain the rationale for regional planning.', 'Design a context-sensitive plan using measurable indicators.'),
  ('class-12-india-people-and-economy', 6, 'Transport and Communication', 'Transport corridors and communication networks connect farms, mines, factories, cities, ports and consumers. Access depends not only on distance but also on cost, reliability, capacity, terrain and the location of network nodes. Improved connections can create new opportunities while leaving remote communities underserved.', 'Choose a commodity and map its likely journey from source to domestic or export market, showing different transport modes.', 'How does terrain influence transport network costs?', 'Why is accessibility more than straight-line distance?', 'Describe how networks support India’s economic regions.', 'Evaluate connectivity using route and access indicators.'),
  ('class-12-india-people-and-economy', 7, 'International Trade', 'India’s external trade reflects domestic production, global demand, logistics, exchange rates and trade policy. Ports, airports, land routes and digital services connect producers to global markets. Export and import patterns change over time, so a sound analysis identifies product group, partner, period and data source.', 'Use an official trade table to compare two product groups over two periods and describe one change carefully.', 'Why should trade comparisons use the same time period and units?', 'How can ports and logistics shape regional trade?', 'Explain factors influencing India’s trade geography.', 'Interpret trade tables and maps with source context.'),
  ('class-12-india-people-and-economy', 8, 'Geographical Perspective on Selected Issues and Problems', 'Environmental and social issues such as pollution, waste, land degradation and water stress have spatial patterns shaped by sources, exposure, infrastructure and policy. Geographic analysis maps where impacts occur, who is affected and how conditions vary across neighbourhoods or regions. Solutions usually combine prevention, monitoring, regulation and community action.', 'Conduct a small local observation audit and map the issue, affected places, possible causes and one evidence-based action.', 'Why is mapping useful for understanding an environmental issue?', 'How can an intervention reduce a symptom without addressing its source?', 'Analyse a selected issue through spatial evidence.', 'Propose a realistic response and indicators for follow-up.');

-- Create or refresh one unit per chapter. The unique constraint on (course_id, position) is deferrable, so update and insert are used instead of ON CONFLICT.
UPDATE public.units u SET title = 'Chapter ' || (ch.chapter_position + 1)::text || ': ' || ch.chapter_title, description = ch.focus
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug
WHERE u.course_id = c.id AND u.position = ch.chapter_position;

INSERT INTO public.units (course_id, title, description, position)
SELECT c.id, 'Chapter ' || (ch.chapter_position + 1)::text || ': ' || ch.chapter_title, ch.focus, ch.chapter_position
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug
WHERE NOT EXISTS (SELECT 1 FROM public.units u WHERE u.course_id = c.id AND u.position = ch.chapter_position);

-- Main study guide and practice activity per chapter. Keep existing lesson IDs where possible.
UPDATE public.lessons l SET title = 'Study guide: ' || ch.chapter_title, description = 'Original eAcharya lesson notes aligned to ' || ch.chapter_title || '.', is_published = true, updated_at = now()
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position
WHERE l.unit_id = u.id AND l.position = 0;
UPDATE public.lessons l SET title = 'Practice worksheet: ' || ch.chapter_title, description = 'Original review questions and an applied geography activity.', is_published = true, updated_at = now()
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position
WHERE l.unit_id = u.id AND l.position = 1;

INSERT INTO public.lessons (unit_id, title, description, position, is_published)
SELECT u.id, 'Study guide: ' || ch.chapter_title, 'Original eAcharya lesson notes aligned to ' || ch.chapter_title || '.', 0, true
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position
WHERE NOT EXISTS (SELECT 1 FROM public.lessons l WHERE l.unit_id = u.id AND l.position = 0);
INSERT INTO public.lessons (unit_id, title, description, position, is_published)
SELECT u.id, 'Practice worksheet: ' || ch.chapter_title, 'Original review questions and an applied geography activity.', 1, true
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position
WHERE NOT EXISTS (SELECT 1 FROM public.lessons l WHERE l.unit_id = u.id AND l.position = 1);

-- Original study notes for every chapter. Preserve any existing video_url/video_sources/allow_download settings.
WITH content_rows AS (
  SELECT l.id AS lesson_id, ARRAY[ch.objective_one, ch.objective_two, 'Use a labelled diagram, map or data source where it helps explain this topic.'] AS objectives,
    '## Core idea' || E'\n\n' || ch.focus || E'\n\n' ||
    '## Think geographically' || E'\n\n' || 'Ask where the pattern occurs, why it varies between places, which processes shape it, and who or what is affected. Use a stated scale and evidence rather than relying only on general impressions.' || E'\n\n' ||
    '## Study routine' || E'\n\n' || '1. Define the central terms in your own words.\n2. Draw a labelled sketch, map, process diagram or short comparison table.\n3. Add one example from India or your local area.\n4. State the data year and source whenever you use statistics.' || E'\n\n' ||
    '## Apply it' || E'\n\n' || ch.activity || E'\n\n' ||
    '## Self-check' || E'\n\n' || '1. ' || ch.question_one || E'\n2. ' || ch.question_two || E'\n\n' ||
    'Study note: This is original eAcharya learning support. Consult the linked current NCERT edition and annual CBSE syllabus for prescribed scope.' AS transcript, 12 AS duration_minutes
  FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position JOIN public.lessons l ON l.unit_id = u.id AND l.position = 0
  UNION ALL
  SELECT l.id AS lesson_id, ARRAY['Revise the core ideas in ' || ch.chapter_title || '.', 'Support each answer with a map, diagram, comparison or evidence where appropriate.'] AS objectives,
    '# Practice worksheet: ' || ch.chapter_title || E'\n\n' ||
    'This is an original eAcharya worksheet aligned to the chapter theme, not copied from the textbook.' || E'\n\n' ||
    '## Short-answer practice' || E'\n\n' || '1. ' || ch.question_one || E'\n2. ' || ch.question_two || E'\n3. Explain one spatial pattern or relationship from this chapter using a labelled sketch, a small table or a reliable example.' || E'\n\n' ||
    '## Applied activity' || E'\n\n' || ch.activity || E'\n\n' ||
    '## Answer-writing checklist' || E'\n\n' || 'Define the term, explain the process or relationship, use a specific example, and end with a brief inference. If you use figures, state their source and year.' AS transcript, 15 AS duration_minutes
  FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position JOIN public.lessons l ON l.unit_id = u.id AND l.position = 1
)
INSERT INTO public.lesson_content (lesson_id, objectives, transcript, duration_minutes)
SELECT lesson_id, objectives, transcript, duration_minutes FROM content_rows
ON CONFLICT (lesson_id) DO UPDATE SET objectives = EXCLUDED.objectives, transcript = EXCLUDED.transcript, duration_minutes = EXCLUDED.duration_minutes, updated_at = now();

-- Hide legacy placeholder resource cards without deleting records or student bookmarks.
UPDATE public.resources SET is_published = false, updated_at = now() WHERE title LIKE '[Sample]%' AND is_published = true;

-- One official textbook reference and one worksheet resource per chapter.
INSERT INTO public.resources (title, description, resource_type, course_id, topic, external_url, is_published)
SELECT 'Official NCERT textbook: ' || b.book_name, 'Open the official NCERT textbook page for this book. Check the current edition and applicable annual syllabus.', 'link', c.id, 'NCERT textbook', b.official_url, true
FROM phase5_books b JOIN public.courses c ON c.slug = b.book_slug
WHERE NOT EXISTS (SELECT 1 FROM public.resources r WHERE r.course_id = c.id AND r.title = 'Official NCERT textbook: ' || b.book_name AND r.resource_type = 'link');

INSERT INTO public.resources (title, description, resource_type, course_id, unit_id, lesson_id, topic, body, is_published)
SELECT 'Practice worksheet: ' || ch.chapter_title, 'Original chapter review, short-answer prompts and one applied geographical task.', 'notes', c.id, u.id, l.id, 'Practice worksheet',
  '# ' || ch.chapter_title || E'\n\n' || 'Original eAcharya practice support; use the current textbook for the complete prescribed chapter.' || E'\n\n' ||
  '1. ' || ch.question_one || E'\n2. ' || ch.question_two || E'\n3. Explain one pattern or relationship using a labelled diagram, map or table.' || E'\n\n' || 'Applied activity: ' || ch.activity || E'\n\n' || 'Check your answers for accurate terminology, a clear explanation, a relevant example and a source/year wherever data is used.', true
FROM phase5_chapters ch JOIN public.courses c ON c.slug = ch.book_slug JOIN public.units u ON u.course_id = c.id AND u.position = ch.chapter_position JOIN public.lessons l ON l.unit_id = u.id AND l.position = 1
WHERE NOT EXISTS (SELECT 1 FROM public.resources r WHERE r.course_id = c.id AND r.unit_id = u.id AND r.title = 'Practice worksheet: ' || ch.chapter_title AND r.resource_type = 'notes');

-- Link the official CIET audio-book catalogue for accessibility. Idempotent by title.
INSERT INTO public.resources (title, description, resource_type, topic, external_url, is_published)
SELECT 'NCERT/CIET Audio Books', 'Browse NCERT audio-book resources by class, subject and language where available.', 'link', 'Accessible learning', 'https://ciet.ncert.gov.in/audio-books', true
WHERE NOT EXISTS (SELECT 1 FROM public.resources WHERE title = 'NCERT/CIET Audio Books' AND resource_type = 'link');

-- Let teaching staff read published course lesson notes, including the read-only curriculum courses where created_by is null.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'lesson_content' AND policyname = 'lesson_content: teaching staff read published') THEN
    EXECUTE $policy$ CREATE POLICY "lesson_content: teaching staff read published" ON public.lesson_content FOR SELECT TO authenticated USING (public.is_teacher_or_admin() AND EXISTS (SELECT 1 FROM public.lessons l JOIN public.units u ON u.id = l.unit_id JOIN public.courses c ON c.id = u.course_id WHERE l.id = lesson_content.lesson_id AND l.is_published = true AND c.status = 'published')) $policy$;
  END IF;
END $$;

DROP TABLE phase5_chapters;
DROP TABLE phase5_books;
